package com.hmdp.ai.infrastructure.external;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.external.*;import com.hmdp.ai.infrastructure.model.SecretNotConfiguredException;import com.hmdp.ai.infrastructure.model.SecretResolutionService;import org.springframework.stereotype.Component;
import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Component public class HttpExternalSearchGateway implements ExternalSearchGateway {private final SafeHttpClient http;private final SecretResolutionService secrets;private final ObjectMapper mapper;private final ReferenceFetcher fetcher;public HttpExternalSearchGateway(SafeHttpClient http,SecretResolutionService secrets,ObjectMapper mapper,ReferenceFetcher fetcher){this.http=http;this.secrets=secrets;this.mapper=mapper;this.fetcher=fetcher;}
    @Override public List<SearchResult>search(String query,int limit,JsonNode c){try{String secretRef=c.path("secretRef").asText();if(secretRef.isEmpty())throw new IllegalArgumentException("PROVIDER_NOT_CONFIGURED");String host=required(c,"allowedHost"),path=c.path("path").asText("/search"),scheme=c.path("scheme").asText("https");String qn=c.path("queryParameter").asText("q"),ln=c.path("limitParameter").asText("limit");String queryString=enc(qn)+"="+enc(query)+"&"+enc(ln)+"="+limit;URI uri=new URI(scheme,null,host,c.path("port").asInt(-1),path,queryString,null);Map<String,String>headers=new LinkedHashMap<>();headers.put("Accept","application/json");headers.put(c.path("secretHeader").asText("Authorization"),c.path("secretPrefix").asText("Bearer ")+secrets.resolve(secretRef));OutboundHttpResponse response=http.execute(new OutboundHttpRequest(uri,"GET",headers,null,Duration.ofMillis(Math.max(100,c.path("timeoutMs").asLong(10000))),Math.max(4096,c.path("maxResponseBytes").asInt(1024*1024)),Collections.singleton("application/json"),c.path("allowPrivateNetwork").asBoolean(false)));if(response.getStatusCode()<200||response.getStatusCode()>=300)throw new IllegalStateException("EXTERNAL_SEARCH_STATUS_"+response.getStatusCode());JsonNode root=mapper.readTree(response.getBody()),items=at(root,c.path("resultsPath").asText("results"));if(!items.isArray())throw new IllegalArgumentException("EXTERNAL_SEARCH_RESPONSE_INVALID");List<SearchResult>results=new ArrayList<>();int fetchTop=Math.max(0,Math.min(limit,c.path("fetchTopPages").asInt(0)));for(JsonNode item:items){if(results.size()>=limit)break;String url=value(item,c,"urlField","url");if(url.isEmpty())continue;String content="";if(results.size()<fetchTop){try{content=fetcher.fetch(url,Math.max(4096,c.path("pageMaxBytes").asInt(512*1024)),Math.max(100,c.path("pageMaxChars").asInt(8000)));}catch(Exception ignored){content="";}}results.add(new SearchResult(value(item,c,"titleField","title"),url,value(item,c,"snippetField","snippet"),instant(value(item,c,"publishedAtField","publishedAt")),Instant.now(),URI.create(url).getHost(),content));}return results;}catch(SecretNotConfiguredException e){throw new IllegalArgumentException("PROVIDER_NOT_CONFIGURED",e);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("EXTERNAL_SEARCH_FAILED",e);}}
    private String required(JsonNode c,String n){String v=c.path(n).asText();if(v.isEmpty())throw new IllegalArgumentException("PROVIDER_NOT_CONFIGURED");return v;}private String enc(String v){return URLEncoder.encode(v,StandardCharsets.UTF_8);}private JsonNode at(JsonNode n,String path){for(String p:path.split("\\.")){n=n.path(p);}return n;}private String value(JsonNode n,JsonNode c,String config,String fallback){return n.path(c.path(config).asText(fallback)).asText("");}private Instant instant(String value){try{return value.isEmpty()?null:Instant.parse(value);}catch(Exception e){return null;}}
}
